        self.pos = 0
        self.current_char = self.expr[self.pos] if self.expr else None

    def error(self):
        raise Exception("Invalid character in the expression")

    def advance(self):
        """Move to the next character in the expression."""
        self.pos += 1
        if self.pos < len(self.expr):
            self.current_char = self.expr[self.pos]
        else:
            self.current_char = None

    def skip_whitespace(self):
        """Skip spaces in the expression."""
        while self.current_char is not None and self.current_char.isspace():
            self.advance()

    def number(self):
        """Parse a number from the expression."""
        result = ''
        while self.current_char is not None and (self.current_char.isdigit() or self.current_char == '.'):
            result += self.current_char
            self.advance()
        return float(result)

    def factor(self):
        """Parse a factor, which can be a number or a parenthesized expression."""
        if self.current_char == '(':
            self.advance()  # Skip '('
            result = self.expr()
            if self.current_char != ')':
                self.error()
            self.advance()  # Skip ')'
            return result
        return self.number()

    def term(self):
        """Parse a term, which can be a product or quotient of factors."""
        result = self.factor()
        while self.current_char is not None and self.current_char in ('*', '/'):
            op = self.current_char
            self.advance()
            if op == '*':
                result *= self.factor()
            elif op == '/':
                result /= self.factor()
        return result

    def expr(self):
        """Parse an expression, which can be a sum or difference of terms."""
        result = self.term()
        while self.current_char is not None and self.current_char in ('+', '-'):
            op = self.current_char
            self.advance()
            if op == '+':
                result += self.term()
            elif op == '-':
                result -= self.term()
        return result

