class Parser:
    def __init__(self, expression: str):
        self.tokens = self.tokenize(expression)
        self.current_token_index = 0

    def tokenize(self, expr: str):
        tokens = []
        i = 0
        while i < len(expr):
            if expr[i].isspace():
                i += 1
                continue
            if expr[i] in "+-*/()":
                tokens.append(expr[i])
                i += 1
            elif expr[i].isdigit() or expr[i] == '.':
                start = i
                while i < len(expr) and (expr[i].isdigit() or expr[i] == '.'):
                    i += 1
                tokens.append(float(expr[start:i]))
            else:
                raise ValueError(f"Unexpected character: {expr[i]}")
        return tokens

    def current_token(self):
        return self.tokens[self.current_token_index] if self.current_token_index < len(self.tokens) else None

    def advance(self):
        self.current_token_index += 1

    def parse_expression(self):
        result = self.parse_term()
        while self.current_token() in ('+', '-'):
            op = self.current_token()
            self.advance()
            if op == '+':
                result += self.parse_term()
            elif op == '-':
                result -= self.parse_term()
        return result

    def parse_term(self):
        result = self.parse_factor()
        while self.current_token() in ('*', '/'):
            op = self.current_token()
            self.advance()
            if op == '*':
                result *= self.parse_factor()
            elif op == '/':
                divisor = self.parse_factor()
                if divisor == 0:
                    raise ValueError("Division by zero")
                result /= divisor
        return result

    def parse_factor(self):
        token = self.current_token()
        if isinstance(token, float):
            self.advance()
            return token
        elif token == '(':
            self.advance()
            result = self.parse_expression()
            if self.current_token() != ')':
                raise ValueError("Mismatched parentheses")
            self.advance()
            return result
        else:
            raise ValueError("Unexpected token: " + str(token))


